#!/usr/bin/env node

import * as readline from 'readline';

// Parse command line arguments
const args = process.argv.slice(2);
if (args.length !== 1 || !['json', 'keys'].includes(args[0])) {
  process.stderr.write('error: usage: cli.js json|keys\n');
  process.exit(2);
}

const mode = args[0];

// Read stdin
async function readInput() {
  const rl = readline.createInterface({
    input: process.stdin,
    output: undefined,
    terminal: false
  });

  const lines = [];
  for await (const line of rl) {
    lines.push(line);
  }
  return lines;
}

class Parser {
  constructor(lines) {
    this.lines = lines;
    this.root = {};
    this.current = this.root;
    this.currentPath = [];
    this.definedKeys = new Set();
    this.definedTables = new Set();
  }

  error(lineNum, reason) {
    process.stderr.write(`error: line ${lineNum}: ${reason}\n`);
    process.exit(2);
  }

  parse() {
    for (let i = 0; i < this.lines.length; i++) {
      const lineNum = i + 1;
      const line = this.lines[i];
      this.parseLine(line, lineNum);
    }
    return this.root;
  }

  parseLine(line, lineNum) {
    // Skip empty lines and comment lines
    const trimmed = line.replace(/^[ \t]*/, '');
    if (trimmed.length === 0 || trimmed[0] === '#' || trimmed[0] === ';') {
      return;
    }

    // Check if it's a header line
    if (line.trim().startsWith('[[')) {
      this.parseArrayTableHeader(line, lineNum);
    } else if (line.trim().startsWith('[')) {
      this.parseTableHeader(line, lineNum);
    } else {
      this.parseKeyValue(line, lineNum);
    }
  }

  parseTableHeader(line, lineNum) {
    const match = line.match(/^\s*\[(.*?)\]\s*(.*)$/);
    if (!match) {
      this.error(lineNum, 'unterminated table header');
    }

    const headerContent = match[1];
    const afterBracket = match[2];

    // Check for trailing text after bracket
    if (afterBracket && !afterBracket.match(/^\s*[#;]/)) {
      this.error(lineNum, 'trailing text after a table header');
    }

    // Parse the dotted name
    const names = this.parseDottedName(headerContent, lineNum);

    // Navigate/create the table path
    let obj = this.root;
    const fullPath = [];

    for (let i = 0; i < names.length; i++) {
      const name = names[i];
      fullPath.push(name);
      const pathStr = fullPath.join('.');

      if (!(name in obj)) {
        obj[name] = {};
      } else if (typeof obj[name] !== 'object' || Array.isArray(obj[name])) {
        this.error(lineNum, `${pathStr} is not a table`);
      }

      obj = obj[name];
    }

    const pathStr = fullPath.join('.');
    if (this.definedTables.has(pathStr)) {
      this.error(lineNum, `table ${pathStr} is defined twice`);
    }
    this.definedTables.add(pathStr);

    this.current = obj;
    this.currentPath = fullPath;
  }

  parseArrayTableHeader(line, lineNum) {
    const match = line.match(/^\s*\[\[(.*?)\]\]\s*(.*)$/);
    if (!match) {
      this.error(lineNum, 'unterminated table header');
    }

    const headerContent = match[1];
    const afterBracket = match[2];

    // Check for trailing text after bracket
    if (afterBracket && !afterBracket.match(/^\s*[#;]/)) {
      this.error(lineNum, 'trailing text after a table header');
    }

    // Parse the dotted name
    const names = this.parseDottedName(headerContent, lineNum);

    // Navigate to parent and get/create the array
    let obj = this.root;
    const fullPath = [];

    for (let i = 0; i < names.length - 1; i++) {
      const name = names[i];
      fullPath.push(name);
      const pathStr = fullPath.join('.');

      if (!(name in obj)) {
        obj[name] = {};
      } else if (typeof obj[name] !== 'object' || Array.isArray(obj[name])) {
        this.error(lineNum, `${pathStr} is not a table`);
      }

      obj = obj[name];
    }

    const arrayName = names[names.length - 1];
    const arrayPath = [...fullPath, arrayName].join('.');

    if (!(arrayName in obj)) {
      obj[arrayName] = [];
    } else if (!Array.isArray(obj[arrayName])) {
      this.error(lineNum, `${arrayPath} is not an array of tables`);
    }

    // Append new table to array
    const newTable = {};
    obj[arrayName].push(newTable);

    this.current = newTable;
    this.currentPath = [...fullPath, arrayName];
  }

  parseKeyValue(line, lineNum) {
    // Find the = sign (not in a string)
    let eqIndex = -1;
    let inString = false;
    let stringChar = null;
    let escaped = false;

    for (let i = 0; i < line.length; i++) {
      const char = line[i];

      if (escaped) {
        escaped = false;
        continue;
      }

      if (char === '\\') {
        escaped = true;
        continue;
      }

      if ((char === '"' || char === "'") && !inString) {
        inString = true;
        stringChar = char;
      } else if (char === stringChar && inString) {
        inString = false;
        stringChar = null;
      } else if (char === '=' && !inString) {
        eqIndex = i;
        break;
      }
    }

    if (eqIndex === -1) {
      this.error(lineNum, 'expected key = value');
    }

    const keyPart = line.substring(0, eqIndex).trim();
    const valuePart = line.substring(eqIndex + 1);

    // Parse the key (dotted name)
    const keys = this.parseDottedName(keyPart, lineNum);

    // Parse the value
    const [value, afterValue] = this.parseValue(valuePart, lineNum);

    // Check for trailing text after value
    const trimmed = afterValue.replace(/^[ \t]*/, '');
    if (trimmed && !trimmed.match(/^[#;]/)) {
      this.error(lineNum, 'trailing text after a value');
    }

    // Navigate through the key path and set the value
    let obj = this.current;
    for (let i = 0; i < keys.length - 1; i++) {
      const key = keys[i];
      const pathKey = [...this.currentPath, ...keys.slice(0, i + 1)].join('.');

      if (!(key in obj)) {
        obj[key] = {};
      } else if (typeof obj[key] !== 'object' || Array.isArray(obj[key])) {
        this.error(lineNum, `${pathKey} is not a table`);
      }

      obj = obj[key];
    }

    const finalKey = keys[keys.length - 1];
    const fullPath = [...this.currentPath, ...keys].join('.');

    if (finalKey in obj) {
      this.error(lineNum, `key ${fullPath} is defined twice`);
    }

    obj[finalKey] = value;
  }

  parseDottedName(nameStr, lineNum) {
    const parts = nameStr.split('.');
    const names = [];

    for (const part of parts) {
      const trimmed = part.trim();
      if (!trimmed) {
        this.error(lineNum, 'expected a name');
      }

      let name;
      if (trimmed[0] === '"' || trimmed[0] === "'") {
        name = this.parseQuotedString(trimmed, lineNum);
      } else {
        // Bare word
        const match = trimmed.match(/^[A-Za-z0-9_-]+/);
        if (!match) {
          this.error(lineNum, 'expected a name');
        }
        name = match[0];
      }

      names.push(name);
    }

    return names;
  }

  parseValue(valueStr, lineNum) {
    const trimmed = valueStr.replace(/^[ \t]*/, '');

    if (trimmed.length === 0) {
      this.error(lineNum, 'expected a value');
    }

    const char = trimmed[0];

    // Boolean
    if (trimmed.startsWith('true')) {
      const rest = trimmed.substring(4);
      const afterValue = this.extractAfterValue(rest, lineNum);
      return [true, afterValue];
    }
    if (trimmed.startsWith('false')) {
      const rest = trimmed.substring(5);
      const afterValue = this.extractAfterValue(rest, lineNum);
      return [false, afterValue];
    }

    // String
    if (char === '"') {
      const [str, rest] = this.parseBasicString(trimmed, lineNum);
      const afterValue = this.extractAfterValue(rest, lineNum);
      return [str, afterValue];
    }
    if (char === "'") {
      const [str, rest] = this.parseLiteralString(trimmed, lineNum);
      const afterValue = this.extractAfterValue(rest, lineNum);
      return [str, afterValue];
    }

    // Array
    if (char === '[') {
      return this.parseArray(trimmed, lineNum);
    }

    // Inline table
    if (char === '{') {
      return this.parseInlineTable(trimmed, lineNum);
    }

    // Number or invalid
    const numberMatch = trimmed.match(/^[+-]?(?:0|[1-9](?:_?[0-9])*)/);
    if (numberMatch) {
      const numberStr = numberMatch[0];
      const rest = trimmed.substring(numberStr.length);

      // Check if it's a float
      if (rest.match(/^\./) || rest.match(/^[eE]/)) {
        const floatMatch = rest.match(/^\.(?:[0-9](?:_?[0-9])*)?(?:[eE][+-]?(?:[0-9](?:_?[0-9])*))*/);
        if (floatMatch) {
          const floatFull = numberStr + floatMatch[0];
          const afterFloat = rest.substring(floatMatch[0].length);
          const afterValue = this.extractAfterValue(afterFloat, lineNum);
          return [parseFloat(floatFull.replace(/_/g, '')), afterValue];
        } else if (rest.match(/^[eE]/)) {
          const expMatch = rest.match(/^[eE][+-]?(?:[0-9](?:_?[0-9])*)/);
          if (expMatch) {
            const floatFull = numberStr + expMatch[0];
            const afterFloat = rest.substring(expMatch[0].length);
            const afterValue = this.extractAfterValue(afterFloat, lineNum);
            return [parseFloat(floatFull.replace(/_/g, '')), afterValue];
          }
        }
      }

      // It's an integer
      const afterValue = this.extractAfterValue(rest, lineNum);
      return [parseInt(numberStr.replace(/_/g, ''), 10), afterValue];
    }

    // Invalid value - extract the word that was attempted
    const invalidMatch = trimmed.match(/^[A-Za-z0-9_+-]*/);
    const invalidWord = invalidMatch ? invalidMatch[0] : '';
    this.error(lineNum, `invalid value ${invalidWord || trimmed.split(/[\s,\]\}#;]/)[0]}`);
  }

  extractAfterValue(rest, lineNum) {
    // Check what comes after the value
    const trimmed = rest.replace(/^[ \t]*/, '');
    if (trimmed && !trimmed.match(/^[,\]\}#;]/)) {
      // For numbers, a # with no space means it's part of the value and invalid
      if (trimmed[0] === '#') {
        this.error(lineNum, 'trailing text after a value');
      }
    }
    return rest;
  }

  parseBasicString(str, lineNum) {
    if (str[0] !== '"') {
      this.error(lineNum, 'expected a string');
    }

    let result = '';
    let i = 1;

    while (i < str.length) {
      const char = str[i];

      if (char === '"') {
        return [result, str.substring(i + 1)];
      }

      if (char === '\\') {
        if (i + 1 >= str.length) {
          this.error(lineNum, 'unterminated string');
        }

        const nextChar = str[i + 1];
        switch (nextChar) {
          case '"':
            result += '"';
            i += 2;
            break;
          case '\\':
            result += '\\';
            i += 2;
            break;
          case 'n':
            result += '\n';
            i += 2;
            break;
          case 't':
            result += '\t';
            i += 2;
            break;
          case 'r':
            result += '\r';
            i += 2;
            break;
          case '0':
            result += '\0';
            i += 2;
            break;
          case 'u':
            if (i + 5 >= str.length) {
              this.error(lineNum, 'invalid escape \\u');
            }
            const hexStr = str.substring(i + 2, i + 6);
            if (!/^[0-9a-fA-F]{4}$/.test(hexStr)) {
              this.error(lineNum, 'invalid escape \\u');
            }
            result += String.fromCharCode(parseInt(hexStr, 16));
            i += 6;
            break;
          default:
            this.error(lineNum, `invalid escape \\${nextChar}`);
        }
      } else {
        result += char;
        i += 1;
      }
    }

    this.error(lineNum, 'unterminated string');
  }

  parseLiteralString(str, lineNum) {
    if (str[0] !== "'") {
      this.error(lineNum, 'expected a string');
    }

    let i = 1;
    while (i < str.length) {
      if (str[i] === "'") {
        return [str.substring(1, i), str.substring(i + 1)];
      }
      i += 1;
    }

    this.error(lineNum, 'unterminated string');
  }

  parseQuotedString(str, lineNum) {
    if (str[0] === '"') {
      return this.parseBasicString(str, lineNum)[0];
    } else if (str[0] === "'") {
      return this.parseLiteralString(str, lineNum)[0];
    }
    this.error(lineNum, 'expected a string');
  }

  parseArray(str, lineNum) {
    if (str[0] !== '[') {
      this.error(lineNum, 'unterminated array');
    }

    const array = [];
    let i = 1;

    while (i < str.length) {
      const char = str[i];

      // Skip whitespace and comments
      if (char === ' ' || char === '\t' || char === '\n') {
        i += 1;
        continue;
      }

      if (char === ']') {
        const rest = str.substring(i + 1);
        const afterValue = this.extractAfterValue(rest, lineNum);
        return [array, afterValue];
      }

      if (char === '#' || char === ';') {
        this.error(lineNum, 'unterminated array');
      }

      // Parse a value
      const valueStr = str.substring(i);
      const [value, afterValue] = this.parseValue(valueStr, lineNum);
      array.push(value);

      i = str.length - afterValue.length;

      // Skip whitespace
      while (i < str.length && (str[i] === ' ' || str[i] === '\t' || str[i] === '\n')) {
        i += 1;
      }

      if (i >= str.length) {
        this.error(lineNum, 'unterminated array');
      }

      if (str[i] === ',') {
        i += 1;
        // Skip whitespace after comma
        while (i < str.length && (str[i] === ' ' || str[i] === '\t' || str[i] === '\n')) {
          i += 1;
        }
      } else if (str[i] === ']') {
        continue;
      } else if (str[i] === '#' || str[i] === ';') {
        this.error(lineNum, 'unterminated array');
      } else {
        this.error(lineNum, 'unterminated array');
      }
    }

    this.error(lineNum, 'unterminated array');
  }

  parseInlineTable(str, lineNum) {
    if (str[0] !== '{') {
      this.error(lineNum, 'unterminated inline table');
    }

    const table = {};
    let i = 1;

    while (i < str.length) {
      const char = str[i];

      // Skip whitespace
      if (char === ' ' || char === '\t') {
        i += 1;
        continue;
      }

      if (char === '}') {
        const rest = str.substring(i + 1);
        const afterValue = this.extractAfterValue(rest, lineNum);
        return [table, afterValue];
      }

      if (char === '#' || char === ';' || char === '\n') {
        this.error(lineNum, 'unterminated inline table');
      }

      // Parse key = value
      const remainingStr = str.substring(i);
      let eqIndex = -1;
      let inString = false;
      let stringChar = null;
      let escaped = false;

      for (let j = 0; j < remainingStr.length; j++) {
        const c = remainingStr[j];

        if (escaped) {
          escaped = false;
          continue;
        }

        if (c === '\\') {
          escaped = true;
          continue;
        }

        if ((c === '"' || c === "'") && !inString) {
          inString = true;
          stringChar = c;
        } else if (c === stringChar && inString) {
          inString = false;
          stringChar = null;
        } else if (c === '=' && !inString) {
          eqIndex = j;
          break;
        }
      }

      if (eqIndex === -1) {
        this.error(lineNum, 'expected = in an inline table');
      }

      const keyPart = remainingStr.substring(0, eqIndex).trim();
      const keyNames = this.parseDottedName(keyPart, lineNum);

      if (keyNames.length !== 1) {
        this.error(lineNum, 'expected key = value');
      }

      const key = keyNames[0];
      if (key in table) {
        this.error(lineNum, 'expected key = value');
