{"file_path":"src/parse.js","content":"/**
 * The parser for the configuration document. It turns the lines of the
 * document into a tree of tagged nodes:
 *
 *   { kind: 'table',   value: Map<string, node> }
 *   { kind: 'array',   value: node[], tables: boolean }
 *   { kind: 'string',  value: string }
 *   { kind: 'integer', value: number }
 *   { kind: 'float',   value: number }
 *   { kind: 'boolean', value: boolean }
 *
 * Tables are held in a Map so that any key text, `__proto__` included, is
 * carried faithfully and in the order it arrived; the printers sort.
 */

export class ParseError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

const BARE = /[A-Za-z0-9_-]/
const INTEGER = /^[+-]?[0-9]+(?:_[0-9]+)*$/
const FLOAT = /^[+-]?[0-9]+(?:_[0-9]+)*(?:\.[0-9]+(?:_[0-9]+)*)?(?:[eE][+-]?[0-9]+(?:_[0-9]+)*)?$/
const HEX4 = /^[0-9a-fA-F]{4}$/

function newTable() {
  return { kind: 'table', value: new Map() }
}

function newArray(tables) {
  return { kind: 'array', value: [], tables }
}

function isSpace(c) {
  return c === ' ' || c === '\t'
}

function isComment(c) {
  return c === '#' || c === ';'
}

/** Joins a path prefix and a key with a dot, the root prefix being empty. */
function joinKey(prefix, key) {
  return prefix === '' ? key : `${prefix}.${key}`
}

/** A scanner over one line of the document. */
class Line {
  constructor(text, number) {
    this.text = text
    this.number = number
    this.pos = 0
  }

  fail(reason) {
    throw new ParseError(this.number, reason)
  }

  done() {
    return this.pos >= this.text.length
  }

  peek() {
    return this.text[this.pos]
  }

  next() {
    return this.text[this.pos++]
  }

  skipSpace() {
    while (!this.done() && isSpace(this.peek())) this.pos += 1
  }

  /** True once nothing but a comment is left. */
  atEnd() {
    return this.done() || isComment(this.peek())
  }

  // --- names ---------------------------------------------------------------

  name() {
    const c = this.peek()
    if (c === '"') return this.basicString()
    if (c === "'") return this.literalString()
    const start = this.pos
    while (!this.done() && BARE.test(this.peek())) this.pos += 1
    if (this.pos === start) this.fail('expected a name')
