    if (keys.length === 0) return '{}'
    const members = keys.map(
      (key) => `${inner}${JSON.stringify(key)}: ${render(node.value.get(key), inner)}`
    )
    return `{\n${members.join(',\n')}\n${indent}}`
  }
  if (node.kind === 'array') {
    if (node.value.length === 0) return '[]'
    const items = node.value.map((item) => `${inner}${render(item, inner)}`)
    return `[\n${items.join(',\n')}\n${indent}]`
  }
  return JSON.stringify(node.value)
}

export function toJson(root) {
  return `${render(root, '')}\n`
}

export function toKeys(root) {
  const lines = []
  const walk = (node, path) => {
    if (node.kind === 'table') {
      for (const key of sortedKeys(node)) {
        const child = node.value.get(key)
        const childPath = path === '' ? key : `${path}.${key}`
        lines.push(`${childPath} ${child.kind}`)
        walk(child, childPath)
      }
    } else if (node.kind === 'array') {
      node.value.forEach((item, index) => {
        const childPath = `${path}[${index}]`
        lines.push(`${childPath} ${item.kind}`)
        walk(item, childPath)
      })
    }
  }
  walk(root, '')
  return lines.map((line) => `${line}\n`).join('')
}
"}

