{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */

import { readFileSync } from 'node:fs'
import { ParseError, parseDocument } from './parse.js'
import { toJson, toKeys } from './format.js'

function die(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exitCode = 2
}

function readInput() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function main(argv) {
  const mode = argv[0]
  if (argv.length !== 1 || (mode !== 'json' && mode !== 'keys')) {
    die('usage: cli.js json|keys')
    return
  }

  const lines = readInput().split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  let output
  try {
    const document = parseDocument(lines)
    output = mode === 'json' ? toJson(document) : toKeys(document)
  } catch (error) {
    if (error instanceof ParseError) {
      die(`line ${error.line}: ${error.reason}`)
      return
    }
    throw error
  }
  process.stdout.write(output)
}

main(process.argv.slice(2))
"}

